14	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
15	import { withAction } from "@/actions/_lib/with-action";
16	import { isEnabled } from "@/lib/feature-flags";
17	import { can } from "@/lib/permissions";
18	import { searchQuerySchema, type SearchQueryInput } from "@/schemas/search";
19	import { buildFlagContext } from "@/server/services/feature-flag-service";
20	import { getOrganizationSummary } from "@/server/services/organization-service";
21	import { search, type SearchHit } from "@/server/services/search-service";
22	import type { ActionResult } from "@/types/api";
23	
24	const run = withAction<typeof searchQuerySchema, SearchHit[]>(
